preRequestScript:
// Paste into Collection pre-request scripts.
const tenant = pm.environment.get('B2C_TENANT_NAME');
const clientId = pm.environment.get('B2C_B2B_CLIENT_ID');
const clientSecret = pm.environment.get('B2C_B2B_CLIENT_SECRET');
const scope = pm.environment.get('B2C_SCOPE');
const url = `https://${tenant}.b2clogin.com/${tenant}.onmicrosoft.com/oauth2/v2.0/token?p=B2C_1A_ClientCredentials`;
pm.sendRequest({
  url,
  method: 'POST',
  header: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: {
    mode: 'urlencoded',
    urlencoded: [
      { key: 'grant_type', value: 'client_credentials' },
      { key: 'client_id', value: clientId },
      { key: 'client_secret', value: clientSecret },
      { key: 'scope', value: scope }
    ]
  }
}, (err, res) => {
  if (err) { console.error(err); return; }
  pm.environment.set('access_token', res.json().access_token);
});
